"use client";
import Link from "next/link";
import {useEffect,useState,type FormEvent} from "react";
import {listMaintenanceVendors,createMaintenanceVendor,updateMaintenanceVendor,type MaintenanceVendor,type MaintenanceVendorInput,type TicketCategory} from "@/lib/api/maintenance";
const categories=["plumbing","electrical","heating","cooling","appliance","doors_locks_windows","pests","exterior_grounds","structural","water_leak","no_heat","gas_smell","no_power","security","other"] as TicketCategory[];
const empty:MaintenanceVendorInput={name:"",phone_e164:"",trades:[],insurance_expiry:null,wcb_expiry:null,notes:null,is_active:true};
const input="mt-1 min-h-11 w-full rounded-xl border border-[var(--ch-border)] bg-[var(--ch-surface-strong)] px-3 py-2 text-sm";
export default function MaintenanceVendors(){
 const[vendors,setVendors]=useState<MaintenanceVendor[]>([]),[showInactive,setShowInactive]=useState(false),[editing,setEditing]=useState<string|null>(null),[form,setForm]=useState<MaintenanceVendorInput>({...empty}),[busy,setBusy]=useState(false),[error,setError]=useState(""),[notice,setNotice]=useState(""),[loaded,setLoaded]=useState(false);
 async function load(){setVendors(await listMaintenanceVendors(showInactive));setLoaded(true);}
 useEffect(()=>{listMaintenanceVendors(showInactive).then(v=>{setVendors(v);setLoaded(true);}).catch(e=>setError(e.message));},[showInactive]);
 function edit(v:MaintenanceVendor){setEditing(v.id);const{id,sms_opted_out,...values}=v;void id;void sms_opted_out;setForm(values);setNotice("");}
 function reset(){setEditing(null);setForm({...empty});}
 async function save(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{if(editing)await updateMaintenanceVendor(editing,form);else await createMaintenanceVendor(form);await load();setNotice(editing?"Vendor updated.":"Vendor created.");reset();}catch(e){setError(e instanceof Error?e.message:"Could not save vendor");}finally{setBusy(false);}}
 async function toggle(v:MaintenanceVendor){setBusy(true);setError("");try{await updateMaintenanceVendor(v.id,{is_active:!v.is_active});await load();if(editing===v.id)reset();setNotice(v.is_active?"Vendor deactivated. Their work-order links are revoked.":"Vendor reactivated. New work-order links are required.");}catch(e){setError(e instanceof Error?e.message:"Could not update vendor");}finally{setBusy(false);}}
 return <main className="min-h-screen bg-[var(--ch-page-bg)] p-5 sm:p-8"><div className="mx-auto max-w-7xl"><Link className="text-sm text-[var(--ch-accent)]" href="/rentals/maintenance">← Maintenance queue</Link><h1 className="mt-3 text-3xl font-semibold">Maintenance vendors</h1><p className="mt-2 text-sm text-[var(--ch-text-muted)]">Only active vendors appear in assignment. Active phone numbers must be unique.</p>
 {error&&<p role="alert" className="my-4 rounded-xl border border-[var(--ch-error-border)] bg-[var(--ch-error-bg)] p-3">{error}</p>}{notice&&<p role="status" className="my-4 rounded-xl border border-[var(--ch-success-border)] bg-[var(--ch-success-bg)] p-3">{notice}</p>}
 <div className="mt-6 grid items-start gap-6 xl:grid-cols-[1.1fr_1fr]"><section className="overflow-hidden rounded-2xl border border-[var(--ch-border)] bg-[var(--ch-surface)]"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--ch-border)] p-5"><h2 className="font-semibold">Vendors ({vendors.length})</h2><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={showInactive} onChange={e=>setShowInactive(e.target.checked)}/> Show inactive</label></div><div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="bg-[var(--ch-surface-muted)] text-xs text-[var(--ch-text-muted)]"><tr><th className="p-4">Vendor</th><th className="p-4">Compliance</th><th className="p-4">Actions</th></tr></thead><tbody>{vendors.map(v=><tr key={v.id} className="border-t border-[var(--ch-border)]"><td className="p-4"><p className="font-semibold">{v.name} {!v.is_active&&<span className="text-xs text-[var(--ch-text-muted)]">(inactive)</span>}</p><p className="mt-1 text-xs">{v.phone_e164}</p>{v.sms_opted_out&&<p className="mt-1 text-xs text-[var(--ch-text-muted)]">SMS opted out — contact must opt in by START</p>}<p className="mt-1 text-xs text-[var(--ch-text-muted)]">{v.trades.map(t=>t.replaceAll("_"," ")).join(", ")||"General"}</p></td><td className="p-4 text-xs"><p>Insurance: {v.insurance_expiry||"Not recorded"}</p><p className="mt-1">WCB: {v.wcb_expiry||"Not recorded"}</p></td><td className="p-4"><button className="block min-h-10 font-semibold text-[var(--ch-accent)]" onClick={()=>edit(v)} disabled={busy}>Edit</button><button className="min-h-10 text-xs underline disabled:opacity-50" disabled={busy} onClick={()=>toggle(v)}>{v.is_active?"Deactivate":"Reactivate"}</button></td></tr>)}</tbody></table>{!vendors.length&&<p className="p-6 text-sm text-[var(--ch-text-muted)]">{loaded?"No vendors yet. Create the first vendor using the form.":"Loading vendors…"}</p>}</div></section>
 <form onSubmit={save} className="space-y-4 rounded-2xl border border-[var(--ch-border)] bg-[var(--ch-surface)] p-5"><div className="flex items-center justify-between"><h2 className="text-lg font-semibold">{editing?"Edit vendor":"New vendor"}</h2>{editing&&<button type="button" className="min-h-10 text-sm underline" onClick={reset}>Cancel edit</button>}</div>
 <label className="block text-sm">Name *<input className={input} required maxLength={200} value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label className="block text-sm">Phone *<input type="tel" required className={input} placeholder="+12045551234" value={form.phone_e164} onChange={e=>setForm({...form,phone_e164:e.target.value})}/></label><p className="text-xs text-[var(--ch-text-muted)]">Saved in E.164 format. Creating a vendor does not send a text.</p>
 <fieldset><legend className="mb-2 text-sm">Trades</legend><div className="grid grid-cols-2 gap-2">{categories.map(c=><label key={c} className="flex items-center gap-2 text-xs"><input type="checkbox" checked={form.trades.includes(c)} onChange={e=>setForm({...form,trades:e.target.checked?[...form.trades,c]:form.trades.filter(t=>t!==c)})}/>{c.replaceAll("_"," ")}</label>)}</div></fieldset>
 <div className="grid gap-3 sm:grid-cols-2"><label className="text-sm">Insurance expiry<input type="date" className={input} value={form.insurance_expiry||""} onChange={e=>setForm({...form,insurance_expiry:e.target.value||null})}/></label><label className="text-sm">WCB expiry<input type="date" className={input} value={form.wcb_expiry||""} onChange={e=>setForm({...form,wcb_expiry:e.target.value||null})}/></label></div><label className="block text-sm">Notes<textarea rows={3} maxLength={5000} className={input} value={form.notes||""} onChange={e=>setForm({...form,notes:e.target.value||null})}/></label><label className="flex items-center gap-3 text-sm"><input type="checkbox" checked={form.is_active} onChange={e=>setForm({...form,is_active:e.target.checked})}/> Active</label><button className="min-h-11 rounded-xl bg-[var(--ch-accent)] px-6 text-sm font-semibold text-white disabled:opacity-50" disabled={busy}>{busy?"Saving…":editing?"Save changes":"Create vendor"}</button>
 </form></div></div></main>;
}
